package cc.ataglace.molebutter.marketplace.internal;
import java.util.*;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.ObjectMapper;
import cc.ataglace.molebutter.marketplace.api.*;
import cc.ataglace.molebutter.marketplace.api.MarketplaceEditing.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.*;
class TargetComparisonsTest {
 final MarketplaceDrafts.Document d=new ObjectMapper().readValue("{\"common\":{},\"options\":[],\"media\":{},\"delivery\":{},\"markets\":{},\"selectedMarkets\":[]}",MarketplaceDrafts.Document.class);
 MarketplaceProductAdapter adapter(List<Change> fields){var a=mock(MarketplaceProductAdapter.class);when(a.comparisonSupported(any())).thenCallRealMethod();when(a.comparisonValue(any(),any())).thenCallRealMethod();when(a.comparisonDisplay(any(),any())).thenCallRealMethod();when(a.comparisonFields(any())).thenReturn(fields);when(a.observedComparisonFields(any())).thenReturn(fields);return a;}
 @Test void absentSavedValuesCannotBeReplayedAndUnverifiedTargetsCannotBeAdopted(){var a=adapter(List.of(new Change("field",null,"0")));var t=new Target("NAVER","UPDATE","READY",null,null,d);var row=TargetComparisons.compare(a,t,null,1,1).rows().getFirst();assertThat(row.savedKnown()).isFalse();assertThat(row.replayAllowed()).isFalse();assertThat(row.adoptAllowed()).isTrue();assertThat(TargetComparisons.compare(a,new Target("NAVER","UPDATE","DELETED",null,null,d),null,1,1).rows()).isEmpty();}
 @Test void failedObservationDoesNotInventAComparisonFromItsPreservedDocument(){var a=adapter(List.of(new Change("field",null,"0")));var saved=new TargetEditStore.SavedTarget(null,d,List.of(new ConflictKey("field",null)),List.of(),null);assertThat(TargetComparisons.compare(a,new Target("COUPANG","UPDATE","FAILED",null,"connection mismatch",d),saved,1,1).rows()).isEmpty();}
 @Test void numericPersistenceNarrowingIsSemanticButDateTimeDifferenceIsNotIgnored(){assertThat(TargetComparisons.equal(0L,0)).isTrue();assertThat(TargetComparisons.equal(Map.of("a",List.of(128000L)),Map.of("a",List.of(128000)))).isTrue();assertThat(TargetComparisons.equal("2099-12-31T00:00:00","2099-12-31T23:59:00")).isFalse();assertThat(TargetComparisons.equal("",null)).isFalse();}
 @Test void unknownObservedFieldNeverBecomesAnEmptyMarketValue(){var a=adapter(List.of(new Change("partner.images",null,List.of())));when(a.observedComparisonFields(any())).thenReturn(List.of());var saved=new TargetEditStore.SavedTarget(null,d,List.of(new ConflictKey("partner.images",null)),List.of(),null);var row=TargetComparisons.compare(a,new Target("ELEVENST","UPDATE","READY",null,null,d),saved,1,1).rows().getFirst();assertThat(row.savedKnown()).isTrue();assertThat(row.observedKnown()).isFalse();assertThat(row.adoptAllowed()).isFalse();assertThat(row.replayAllowed()).isFalse();}
 @Test void absentIntentAndEmptyRemoteAreOmittedButZeroAndFalseRemainInformation(){var a=adapter(List.of(new Change("empty",null,""),new Change("null",null,null),new Change("list",null,List.of()),new Change("zero",null,0),new Change("bool",null,false)));var result=TargetComparisons.compare(a,new Target("NAVER","UPDATE","READY",null,null,d),null,1,1);assertThat(result.rows()).extracting(ComparisonRow::key).containsExactly("zero|","bool|");assertThat(result.rows()).extracting(ComparisonRow::kind).containsOnly("INFORMATION");assertThat(result.policyVersion()).isEqualTo(2);}
}
